"""Load V1 node identities generated by tools/provision.py."""
import json
from pathlib import Path

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

from common.certs import CA, certificate_from_dict


def load_bundle(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def load_public_only_ca(pem_text):
    # Build a verification-only CA object. Its signing private key is never
    # included in either machine's runtime bundle.
    ca = object.__new__(CA)
    ca.suite = "v1"
    ca.priv = None
    ca.pub = serialization.load_pem_public_key(pem_text.encode("ascii"))
    ca._serial = 0
    ca.revoked = set()
    if not isinstance(ca.pub, rsa.RSAPublicKey):
        raise ValueError("V1 CA public key must be RSA")
    return ca


def apply_identity(node, identity_data):
    node.priv = serialization.load_pem_private_key(
        identity_data["private_key_pem"].encode("ascii"), password=None)
    node.pub = node.priv.public_key()
    node.cert = certificate_from_dict(identity_data["certificate"])
    if node.cert.subject != identity_data["name"]:
        raise ValueError("identity name does not match certificate subject")
    if node.cert.suite != "v1":
        raise ValueError("distributed demo supports V1 identities only")
    return node
